import * as React from 'react';
import { cn } from '@/lib/utils';

export type AuthLayoutProps = React.HTMLAttributes<HTMLDivElement> & {
  title: string;
  description?: string;
  /** Brand/mark above the card. */
  brand?: React.ReactNode;
  /** Links or legal copy under the card. */
  footer?: React.ReactNode;
  /** Rendered inside the card under the heading. */
  children?: React.ReactNode;
  /** Card width preset (default 'md'). */
  size?: 'sm' | 'md' | 'lg';
};

const sizeClasses: Record<NonNullable<AuthLayoutProps['size']>, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
};

/**
 * Centered auth surface: brand mark, title/description, the form card and a
 * footer slot. Keeps sign-in, sign-up, reset and verify screens visually
 * identical without each page re-deriving the layout.
 */
export const AuthLayout = React.forwardRef<HTMLDivElement, AuthLayoutProps>(function AuthLayout(
  { title, description, brand, footer, children, size = 'md', className, ...props },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn('flex min-h-screen flex-col items-center justify-center bg-muted/30 px-4 py-12', className)}
      {...props}
    >
      {brand && <div className="mb-6">{brand}</div>}
      <div className={cn('w-full rounded-xl border border-border bg-card p-6 shadow-sm sm:p-8', sizeClasses[size])}>
        <h1 className="text-xl font-semibold tracking-tight">{title}</h1>
        {description && <p className="mt-1 text-sm text-muted-foreground">{description}</p>}
        <div className="mt-6">{children}</div>
      </div>
      {footer && <div className="mt-6 text-center text-sm text-muted-foreground">{footer}</div>}
    </div>
  );
});

{
  "id": "auth-layout",
  "name": "AuthLayout",
  "tier": "organism",
  "description": "Centered authentication surface: brand, title/description, form card and footer, with size presets.",
  "designIntent": "Sign-in, sign-up, reset and verify screens should look identical. AuthLayout owns the centered card, brand slot and footer so auth pages only supply the form.",
  "props": [
    {
      "name": "title",
      "type": "string",
      "required": true,
      "description": "Card heading (h1)."
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Supporting line under the heading."
    },
    {
      "name": "brand",
      "type": "ReactNode",
      "required": false,
      "description": "Mark rendered above the card."
    },
    {
      "name": "footer",
      "type": "ReactNode",
      "required": false,
      "description": "Links/legal copy under the card."
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "required": false,
      "defaultValue": "md",
      "description": "Card width preset.",
      "enum": [
        "sm",
        "md",
        "lg"
      ]
    }
  ],
  "examples": [
    {
      "title": "Sign in",
      "code": "<AuthLayout\n  title=\"Sign in\"\n  description=\"Welcome back.\"\n  brand={<Logo />}\n  footer={<a href=\"/signup\">Create account</a>}\n>\n  <SignInForm />\n</AuthLayout>",
      "description": "Form lives inside the card."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't nest another full-height page",
      "explanation": "AuthLayout already owns min-h-screen centering.",
      "example": "// Avoid\n<div className=\"min-h-screen\"><AuthLayout … /></div>"
    }
  ],
  "accessibility": [
    {
      "feature": "One h1",
      "implementation": "Renders the page heading",
      "userRequirements": "Don't add another h1 inside the form"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Titles",
      "guidelines": [
        "Action-oriented",
        "Sentence case"
      ],
      "goodExamples": [
        "Sign in",
        "Create your account"
      ],
      "badExamples": [
        "Login page"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Form",
      "relationship": "Place the Form inside children",
      "example": "<AuthLayout title=\"Sign in\"><Form onSubmit={…}>…</Form></AuthLayout>"
    }
  ],
  "relatedComponents": [
    "Form",
    "PasswordInput",
    "Button"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.5.0",
  "sourceDir": "auth-layout",
  "exportName": "AuthLayout"
}
